import 'package:dio/dio.dart';
import '../../core/network/api_client.dart';
import '../../core/services/session_service.dart';
class AuthRepository { AuthRepository(this._client, this._session); final ApiClient _client; final SessionService _session; Future<void> login(String email, String password) async { final response = await _client.dio.post<Map<String, dynamic>>('/auth/login', data: {'email': email, 'password': password}); await _persist(response.data); } Future<void> register(String name, String email, String password) async { final response = await _client.dio.post<Map<String, dynamic>>('/auth/register', data: {'name': name, 'email': email, 'password': password}); await _persist(response.data); } Future<void> forgotPassword(String email) => _client.dio.post<void>('/auth/forgot-password', data: {'email': email}); Future<void> logout() async { try { await _client.dio.post<void>('/auth/logout'); } on DioException catch (_) { await _session.clear(); return; } await _session.clear(); } Future<bool> hasSession() async => (await _session.accessToken()) != null; Future<void> _persist(Map<String, dynamic>? data) async { final access = data?['accessToken'] as String?; final refresh = data?['refreshToken'] as String?; if (access == null || refresh == null) throw const FormatException('Invalid authentication response'); await _session.save(accessToken: access, refreshToken: refresh); } }
